INSERT INTO factors (code, name, low_label, high_label, category, short_desc, detailed_desc, low_desc, average_desc, high_desc, workplace_impact, sort_order) VALUES
('A', 'Warmth', 'Reserved, Impersonal', 'Warm, People-Oriented', 'Interpersonal', 'Degree of interpersonal warmth, engagement, and emotional closeness with others.', 'Warmth reflects how openly a person connects with people, participates in group activities, and expresses empathy versus preferring solitary focus and objective emotional detachment.', 'Values personal boundaries, privacy, and objectivity. Tends to work independently, focusing on facts rather than emotional nuances.', 'Balances cordiality with necessary professional detachment. Friendly when required without being overly reliant on socializing.', 'Naturally welcoming, expressive, and empathetic. Thrives in collaborative teams and easily builds rapport with diverse individuals.', 'High A excels in client relations, team cohesion, and care roles; Low A excels in technical solitude and objective analysis.', 1),
('B', 'Reasoning', 'Concrete Thinking', 'Abstract Thinking', 'Cognitive', 'Mental processing capacity, conceptual problem-solving, and abstract reasoning.', 'Reasoning measures the preference for theoretical conceptualization and fast pattern recognition versus pragmatic, hands-on, step-by-step logic.', 'Prefers tangible, real-world examples and established procedures over hypothetical models or ambiguity.', 'Handles both concrete tasks and conceptual problem-solving comfortably according to daily job demands.', 'Quick to synthesize complex data, identify underlying systemic patterns, and enjoy intellectual challenges.', 'High B thrives in strategy, complex architecture, and research; Low B excels in straightforward operational execution.', 2),
('C', 'Emotional Stability', 'Reactive, Easily Upset', 'Calm, Steady', 'Emotional', 'Dynamic resilience, emotional equilibrium, and capacity to handle stress constructively.', 'Assesses coping capacity under pressure, consistency of mood, and resilience when faced with sudden obstacles or setbacks.', 'Emotionally sensitive and reactive to stressors. Highly attuned to environmental friction and interpersonal tension.', 'Demonstrates standard resilience; remains steady during normal workloads with occasional stress during severe crises.', 'Remarkably unflappable, composed, and adaptable under high-pressure scenarios and crisis management.', 'High C provides an anchor in chaotic environments; Low C acts as an early sensor for organizational friction.', 3),
('E', 'Dominance', 'Deferential, Cooperative', 'Assertive, Forceful', 'Interpersonal', 'Propensity to take charge, assert opinions, lead, and influence social dynamics.', 'Evaluates the tendency toward assertiveness, direct persuasion, and authority versus accommodation and harmonious compliance.', 'Cooperative, accommodating, and peace-seeking. Prefers consensus and avoids unnecessary confrontation.', 'Asserts viewpoints when appropriate while respecting the authority and input of colleagues.', 'Direct, competitive, and decisive. Naturally assumes leadership and takes initiative to drive outcomes.', 'High E drives initiatives and leads teams; Low E builds collaborative bridges and supports consensus.', 4),
('F', 'Liveliness', 'Serious, Restrained', 'Spontaneous, Enthusiastic', 'Interpersonal', 'Spontaneity, enthusiasm, expressive energy, and cheerfulness.', 'Reflects the degree of spontaneous energy, optimism, and verbal expressiveness compared with measured caution and deliberate restraint.', 'Quiet, prudent, and restrained. Thinks carefully before speaking and takes commitments with sober seriousness.', 'Shows balanced enthusiasm; can be lively in celebratory settings and focused in formal meetings.', 'Energetic, cheerful, and enthusiastic. Brings vitality, humor, and optimism into meetings and social groups.', 'High F energizes morale, sales, and presentations; Low F excels in audit, compliance, and meticulous scrutiny.', 5),
('G', 'Rule-Consciousness', 'Flexible, Non-Conforming', 'Rule-Bound, Dutiful', 'Self-Regulation', 'Adherence to societal rules, moral duty, standards, and institutional guidelines.', 'Measures standard adherence, conscientiousness, and commitment to obligations versus expediency and unconventional flexibility.', 'Flexible, adaptable, and willing to bend formal rules to solve novel problems quickly or challenge conventions.', 'Respects fundamental standards while applying sensible pragmatic judgment when exceptions arise.', 'Highly conscientious, reliable, and dutiful. Values integrity, protocols, and meticulous moral responsibility.', 'High G ensures regulatory compliance, quality control, and reliability; Low G fosters innovative rule-breaking.', 6),
('H', 'Social Boldness', 'Shy, Cautious', 'Bold, Uninhibited', 'Interpersonal', 'Confidence and fearlessness in public speaking, new social situations, and risk exposure.', 'Assesses comfort in high-visibility roles, speaking before strangers, approaching unfamiliar groups, and taking social risks.', 'Sensitive to social scrutiny; prefers small, familiar groups and quiet observation over the spotlight.', 'Comfortable interacting in standard business meetings; balances caution with reasonable social presence.', 'Adventurous, socially confident, and resilient to social rejection. Enjoys networking and large public stages.', 'High H excels in business development, pitching, and media presence; Low H thrives in focused backstage execution.', 7),
('I', 'Sensitivity', 'Tough-Minded, Practical', 'Tender-Minded, Sentimental', 'Emotional', 'Aesthetic appreciation, intuitive empathy, and artistic sensitivity vs pragmatic realism.', 'Evaluates the balance between emotional intuition, artistic depth, and tender sentiment versus utilitarian pragmatism.', 'Practical, realistic, and unsentimental. Focuses on tangible utility, facts, and logical efficiency.', 'Appreciates aesthetic and human factors without losing sight of practical deadlines and resource limits.', 'Imaginative, empathetic, and culturally refined. Sensitive to subtle emotional tones, aesthetics, and nuance.', 'High I contributes design intuition, user empathy, and cultural awareness; Low I maintains hardheaded operational focus.', 8),
('L', 'Vigilance', 'Trusting, Accepting', 'Suspicious, Wary', 'Interpersonal', 'Degree of skepticism, wariness regarding intentions of others vs instinctive trust.', 'Measures how readily a person trusts motives versus maintaining critical skepticism and vigilance against hidden agendas.', 'Unconditionally trusting, tolerant, and forgiving. Believes in the good intentions of others and easily cooperates.', 'Displays realistic caution without being cynically suspicious; verifies facts before making major commitments.', 'Inquisitive, guarded, and discerning. Questions assumptions, scrutinizes motives, and guards against exploitation.', 'High L excels in risk auditing, fraud detection, and legal review; Low L excels in fostering open team trust.', 9),
('M', 'Abstractedness', 'Practical, Grounded', 'Imaginative, Idea-Focused', 'Cognitive', 'Focus on inner ideas, conceptual imagination, and creative reflection vs sensory reality.', 'Distinguishes between a daydreaming, idea-generating mindset and an observant, grounded focus on immediate physical surroundings.', 'Down-to-earth, observant, and practical. Attentive to immediate physical surroundings and actionable details.', 'Balances creative brainstorming with practical execution and day-to-day administrative follow-through.', 'Visionary, introspective, and creative. Absorbed in abstract ideas, theoretical possibilities, and artistic concepts.', 'High M generates breakthrough innovation and long-term vision; Low M manages detail-heavy logistics and operations.', 10),
('N', 'Privateness', 'Open, Forthright', 'Private, Discreet', 'Interpersonal', 'Tendency to keep thoughts and feelings guarded vs being candid, open, and transparent.', 'Assesses diplomatic discretion, self-containment, and calculated presentation versus uninhibited transparency.', 'Direct, candid, and emotionally transparent. Openly shares feelings, thoughts, and opinions without filter.', 'Appropriately diplomatic; shares personal perspectives with trusted colleagues while maintaining professional discretion.', 'Discreet, polished, and socially guarded. Carefully considers what to reveal and maintains a composed personal boundary.', 'High N thrives in confidential negotiations and diplomatic PR; Low N builds fast genuine rapport through authenticity.', 11),
('O', 'Apprehension', 'Self-Assured, Secure', 'Self-Doubting, Worried', 'Emotional', 'Degree of self-confidence and serenity vs self-criticism, anxiety, and vulnerability.', 'Measures feelings of adequacy, self-assurance, and resilience to guilt versus self-scrutiny, self-blame, and anticipatory worry.', 'Confident, unflappable, and self-assured. Rare feelings of guilt or self-doubt; moves on quickly from mistakes.', 'Maintains healthy self-esteem while possessing enough humility to acknowledge errors and learn from criticism.', 'Self-aware, conscientious, and prone to worry. Scrutinizes own performance deeply and cares immensely about outcomes.', 'High O drives perfectionism and high personal standards; Low O provides unwavering confidence in decisive moments.', 12),
('Q1', 'Openness to Change', 'Traditional, Conservative', 'Open to New Experiences', 'Cognitive', 'Receptiveness to novel ideas, unconventional methods, modern experimentation, and reform.', 'Measures preference for established customs, predictable traditions, and time-tested methods versus eagerness to experiment.', 'Values tradition, proven track records, stability, and historical precedent. Skeptical of unproven fads.', 'Welcomes constructive improvements while respecting institutional memory and established foundations.', 'Progressive, inquisitive, and experimental. Eager to challenge status quos, adopt modern tools, and explore uncharted paths.', 'High Q1 drives digital transformation and agile experimentation; Low Q1 preserves organizational continuity.', 13),
('Q2', 'Self-Reliance', 'Group-Oriented, Affiliative', 'Self-Reliant, Solitary', 'Interpersonal', 'Preference for independent decision-making and solitary work vs group consensus.', 'Evaluates the need for collective consultation and community companionship versus autonomous self-sufficiency.', 'Social, team-oriented, and collaborative. Thrives on collective decision-making and group camaraderie.', 'Enjoys team brainstorming but is equally capable of executing independent solo assignments.', 'Autonomous, self-directed, and independent. Prefers making own decisions and working without constant supervision.', 'High Q2 excels in remote autonomy and lone research; Low Q2 excels in building community and cross-functional teams.', 14),
('Q3', 'Perfectionism', 'Unstructured, Flexible', 'Organized, Disciplined', 'Self-Regulation', 'Planfulness, self-control, organizational discipline, and attention to systematic order.', 'Assesses goal-directed willpower, systematic planning, neatness, and self-discipline versus spontaneous flexibility.', 'Tolerant of disorder, spontaneous, and informal. Comfortable improvising on the fly without rigid agendas.', 'Maintains orderly workflows and meets deadlines without becoming overly rigid or obsessive.', 'Methodical, disciplined, and highly structured. Takes pride in precision, organization, and deliberate execution.', 'High Q3 delivers flawless project management and operational rigor; Low Q3 adapts swiftly in chaotic startups.', 15),
('Q4', 'Tension', 'Relaxed, Patient', 'Tense, Impatient', 'Emotional', 'Internal drive, urgent energy, restless tension, and frustration tolerance.', 'Reflects restless energy, drive for immediate action, and irritability versus relaxed tranquility and unhurried composure.', 'Placid, composed, and patient. Rarely feels rushed; maintains a relaxed, tranquil state of mind.', 'Possesses adequate internal motivation to meet deadlines while maintaining basic personal peace.', 'High-octane, driven, and urgently focused on speed. Highly motivated to get things done immediately.', 'High Q4 provides restless drive and urgency to finish tasks; Low Q4 provides patience and soothing composure.', 16);
INSERT INTO domains (code, name, description, sort_order) VALUES
('EX', 'Extraversion', 'Social energy, relational engagement, and assertive public presence.', 1),
('AX', 'Anxiety', 'Vulnerability to emotional reactivity, worry, and nervous tension.', 2),
('TM', 'Tough-Mindedness', 'Pragmatic, cognitive realism vs aesthetic empathy and sensitivity.', 3),
('IN', 'Independence', 'Self-directed assertion, autonomy, and intellectual freedom.', 4),
('SC', 'Self-Control', 'Disciplined impulse regulation, moral conscientiousness, and planfulness.', 5);
